ank_version":10,"item_key":"what_not_to_do_extra_06","prompt":"The final answer is visible, but the record has no qualifying direct observation of independent first-step control. What must the Specialist preserve?","options":[{"key":"a","label":"Leave independent first-step control unresolved until there is qualifying direct evidence; its absence is not a student failure."},{"key":"b","label":"Mark independent first-step control supported because a later correct answer or related dimension looked strong."},{"key":"c","label":"Mark independent first-step control as a capability breakdown because qualifying evidence is missing."},{"key":"d","label":"Reconstruct independent first-step control from a likely explanation and record it as a directly observed response."},{"key":"e","label":"Preserve other reliable observations separately, and let RI-OS request a clean equivalent opportunity if independent first-step control is needed."}],"option_feedback":{"b":"A strong later answer cannot substitute for a direct observation of the exact claim.","c":"Missing evidence is not a student breakdown.","d":"An inference or recollection cannot be substituted for the original observation."},"explanation":"No qualifying direct evidence establishes independent first-step control. Preserve the evidence status without inventing a simulated missing-observation incident. The Specialist must neither score the student weak nor strong from absence; RI-OS determines whether a fresh comparable check is needed.","kind":"missing"},{"assessment_key":"what_not_to_do_mastery_v1","original_bank_version":10,"item_key":"what_not_to_do_extra_07","prompt":"A required Handover claim is unresolved. What is the risk of adding an unauthorized leading method question solely to fill the requested field?","options":[{"key":"a","label":"Leave the unresolved Handover claim unresolved until there is qualifying direct evidence; its absence is not a student failure."},{"key":"b","label":"Preserve other reliable observations separately, and let RI-OS request a clean equivalent opportunity if the unresolved Handover claim is needed."},{"key":"c","label":"Mark the unresolved Handover claim supported because a later correct answer or related dimension looked strong."},{"key":"d","label":"Mark the unresolved Handover claim as a capability breakdown because qualifying evidence is missing."},{"key":"e","label":"Reconstruct the unresolved Handover claim from a likely explanation and record it as a directly observed response."}],"option_feedback":{"c":"A strong later answer cannot substitute for a direct observation of the exact claim.","d":"Missing evidence is not a student breakdown.","e":"An inference or recollection cannot be substituted for the original observation."},"explanation":"No qualifying direct evidence establishes the unresolved Handover claim. Preserve the evidence status without inventing a simulated missing-observation incident. The Specialist must neither score the student weak nor strong from absence; RI-OS determines whether a fresh comparable check is needed.","kind":"missing"},{"assessment_key":"how_to_diagnose_mastery_v1","original_bank_version":19,"item_key":"how_to_diagnose_extra_19","prompt":"A diagnostic evidence question remains unresolved because no qualifying observation establishes the required dimension. Is an additional system-authorized comparable opportunity inconsistent with evidence-complete Diagnosis?","options":[{"key":"a","label":"Mark the unresolved diagnostic dimension supported because a later correct answer or related dimension looked strong."},{"key":"b","label":"Leave the unresolved diagnostic dimension unresolved until there is qualifying direct evidence; its absence is not a student failure."},{"key":"c","label":"Mark the unresolved diagnostic dimension as a capability breakdown because qualifying evidence is missing."},{"key":"d","label":"Reconstruct the unresolved diagnostic dimension from a likely explanation and record it as a directly observed response."},{"key":"e","label":"Preserve other reliable observations separately, and let RI-OS request a clean equivalent opportunity if the unresolved diagnostic dimension is needed."}],"option_feedback":{"a":"A strong later answer cannot substitute for a direct observation of the exact claim.","c":"Missing evidence is not a student breakdown.","d":"An inference or recollection cannot be substituted for the original observation."},"explanation":"No qualifying direct evidence establishes the unresolved diagnostic dimension. Preserve the evidence status without inventing a simulated missing-observation incident. The Specialist must neither score the student weak nor strong from absence; RI-OS determines whether a fresh comparable check is needed.","kind":"missing"},{"assessment_key":"how_to_diagnose_mastery_v1","original_bank_version":19,"item_key":"how_to_diagnose_extra_27","prompt":"A completed problem shows the final answer but not the independent recognition used to choose the method. How should that recognition claim be recorded?","options":[{"key":"a","label":"Mark independent method recognition supported because a later correct answer or related dimension looked strong."},{"key":"b","label":"Mark independent method recognition as a capability breakdown because qualifying evidence is missing."},{"key":"c","label":"Leave independent method recognition unresolved until there is qualifying direct evidence; its absence is not a student failure."},{"key":"d","label":"Reconstruct independent method recognition from a likely explanation and record it as a directly observed response."},{"key":"e","label":"Preserve other reliable observations separately, and let RI-OS request a clean equivalent opportunity if independent method recognition is needed."}],"option_feedback":{"a":"A strong later answer cannot substitute for a direct observation of the exact claim.","b":"Missing evidence is not a student breakdown.","d":"An inference or recollection cannot be substituted for the original observation."},"explanation":"No qualifying direct evidence establishes independent method recognition. Preserve the evidence status without inventing a simulated missing-observation incident. The Specialist must neither score the student weak nor strong from absence; RI-OS determines whether a fresh comparable check is needed.","kind":"missing"}]'::jsonb) AS p(assessment_key text, original_bank_version integer,item_key text,prompt text,options jsonb,option_feedback jsonb,explanation text,kind text);
CREATE TEMP TABLE _ri_exception_bank ON COMMIT DROP AS
 SELECT c.assessment_key,c.bank_version old_version,(SELECT MAX(c2.bank_version)+1 FROM private.specialist_capability_assessment_configs c2 WHERE c2.assessment_key=c.assessment_key) new_version FROM private.specialist_capability_assessment_configs c WHERE c.active=true AND c.assessment_key IN(SELECT DISTINCT assessment_key FROM _ri_exception_patch);
DO $$ BEGIN
 IF (SELECT count(*) FROM _ri_exception_patch) <> 34 THEN RAISE EXCEPTION 'unexpected correction item count'; END IF;
 IF (SELECT count(*) FROM _ri_exception_bank) <> 9 THEN RAISE EXCEPTION 'not all target banks active'; END IF;
 IF EXISTS (SELECT 1 FROM _ri_exception_patch p LEFT JOIN _ri_exception_bank b ON b.assessment_key=p.assessment_key AND b.old_version=p.original_bank_version LEFT JOIN private.specialist_capability_assessment_items i ON i.assessment_key=p.assessment_key AND i.bank_version=p.original_bank_version AND i.item_key=p.item_key WHERE b.assessment_key IS NULL OR i.item_key IS NULL OR i.active IS NOT TRUE) THEN RAISE EXCEPTION 'active source item changed or missing'; END IF;
 IF EXISTS (SELECT 1 FROM _ri_exception_patch p JOIN private.specialist_capability_assessment_items i ON i.assessment_key=p.assessment_key AND i.bank_version=p.original_bank_version AND i.item_key=p.item_key WHERE jsonb_array_length(p.options)<>jsonb_array_length(i.options) OR (SELECT array_agg(v->>'key' ORDER BY ord) FROM jsonb_array_elements(p.options) WITH ORDINALITY t(v,ord)) IS DISTINCT FROM (SELECT array_agg(v->>'key' ORDER BY ord) FROM jsonb_array_elements(i.options) WITH ORDINALITY t(v,ord))) THEN RAISE EXCEPTION 'option keys or count changed'; END IF;
END $$;
INSERT INTO private.specialist_capability_assessment_configs(assessment_key,bank_version,title,assessment_deep_dive_key,evidence_kind,pass_threshold_percent,form_size,max_attempts,retry_cooldown_hours,competency_blueprint,active,created_at,retired_at,review_mode)
SELECT c.assessment_key,b.new_version,c.title,c.assessment_deep_dive_key,c.evidence_kind,c.pass_threshold_percent,c.form_size,c.max_attempts,c.retry_cooldown_hours,c.competency_blueprint,false,NOW(),NULL,false FROM private.specialist_capability_assessment_configs c JOIN _ri_exception_bank b ON b.assessment_key=c.assessment_key AND b.old_version=c.bank_version;
INSERT INTO private.specialist_capability_assessment_items(assessment_key,bank_version,item_key,competency_key,deep_dive_key,prompt,question_kind,options,correct_option_keys,critical_fail_option_keys,critical_boundary_keys,explanation,active,created_at,option_feedback)
SELECT i.assessment_key,b.new_version,i.item_key,i.competency_key,i.deep_dive_key,COALESCE(p.prompt,i.prompt),i.question_kind,COALESCE(p.options,i.options),i.correct_option_keys,i.critical_fail_option_keys,i.critical_boundary_keys,COALESCE(p.explanation,i.explanation),i.active,NOW(),COALESCE(p.option_feedback,i.option_feedback) FROM private.specialist_capability_assessment_items i JOIN _ri_exception_bank b ON b.assessment_key=i.assessment_key AND b.old_version=i.bank_version LEFT JOIN _ri_exception_patch p ON p.assessment_key=i.assessment_key AND p.original_bank_version=i.bank_version AND p.item_key=i.item_key;
DO $$ BEGIN
 IF EXISTS (SELECT 1 FROM _ri_exception_bank b LEFT JOIN (SELECT assessment_key,bank_version,count(*) AS n FROM private.specialist_capability_assessment_items GROUP BY 1,2) old ON old.assessment_key=b.assessment_key AND old.bank_version=b.old_version LEFT JOIN (SELECT assessment_key,bank_version,count(*) AS n FROM private.specialist_capability_assessment_items GROUP BY 1,2) newer ON newer.assessment_key=b.assessment_key AND newer.bank_version=b.new_version WHERE old.n<>newer.n OR newer.n IS NULL) THEN RAISE EXCEPTION 'staged bank count mismatch'; END IF;
 IF EXISTS (SELECT 1 FROM _ri_exception_bank b JOIN private.specialist_capability_assessment_configs c ON c.assessment_key=b.assessment_key AND c.bank_version=b.new_version WHERE c.active OR c.review_mode) THEN RAISE EXCEPTION 'staged version must remain inactive'; END IF;
END $$;
COMMIT;
